// === Uncler M Variant #2: Quantum Armillary Sphere & Emerald Gold Tone ===
// Inspired by OpenProcessing 2955184 'Unusual Globe' by u110137

const num = 180;
let counter = 0;
let mode = 1;
let ang, tang;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	colorMode(HSB, 360, 100, 100, 100);
	ang = createVector(0, 0, 0);
	tang = createVector(HALF_PI, 0, 0);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function draw() {
	let bEnergy = (window.beatEnergy || 0.0);
	let bassE = (window.bassEnergy || 0.0);
	let midE = (window.midEnergy || 0.0);
	let highE = (window.highEnergy || 0.0);

	counter += (1.2 + bassE * 4.0);
	tang.y = cos(frameCount * 0.01) * 1.8;
	tang.x = sin(frameCount * 0.012) * 1.4;
	ang.lerp(tang, 0.06);

	let m = 6 * TAU * cos(counter / 180) / num;
	orbitControl(0, 0, 0.5);
	rotateZ(ang.z);
	rotateY(ang.y + frameCount * 0.008);
	rotateX(ang.x);
	background(160, 90, 8);
	noFill();

	for (let i = 0; i < min(num, frameCount); i++) {
		let a = i * PI / num;
		let r = sin(a) * min(width, height) / 2.2 * (1.0 + bassE * 0.15);

		// Emerald Gold HSL Palette
		let hueVal = (40 + i * 0.7 + (i < num/2 ? 110 : 0) + bassE * 30) % 360;
		let satVal = 75 + sin(i * 0.08) * 20;
		let briVal = 85 + bEnergy * 15;
		stroke(hueVal, satVal, briVal, 80);
		strokeWeight(1.8 + highE * 2.5);

		push();
		switch (mode) {
			case 0:
				rotateZ(2 * (i - num / 2) * m);
				break;
			case 1:
				rotateZ((i < num / 2) * PI);
				rotateY((i - num / 2) * m);
				break;
			case 2:
				rotateZ((i < num / 2) * PI);
				rotateX((i - num / 2) * m);
				break;
		}
		translate(0, 0, cos(a) * min(width, height) / 2.4);
		arc(0, 0, r, r, 0, TWO_PI * (0.5 + midE * 0.2), OPEN, 36);
		pop();
	}
}

if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

